WITH base AS (SELECT *, discount - amount AS discount_minus_amount FROM orders WHERE amount < 1500), summary AS (SELECT QUARTER(order_date) AS order_quarter, ROUND(AVG(discount_minus_amount), 2) AS avg_discount_minus_amount FROM base GROUP BY QUARTER(order_date)) SELECT order_quarter, avg_discount_minus_amount FROM summary WHERE avg_discount_minus_amount < 31 ORDER BY avg_discount_minus_amount DESC, order_quarter
